import React, { useState, useEffect } from 'react';

// 1. Bus Types without seat counts in parentheses
const BUS_TYPES = [
  'Sleeper Class AC Coach',
  'Business / VIP Class AC Coach',
  'Premium Recliner AC Coach',
  'Standard Executive AC Coach',
  'BRTC Double-Decker Highway Bus',
  'Standard Non-AC Highway Coach',
  'Economy / High-Density Non-AC Bus',
  'Mini / Hilly Route Regional Coach'
];

const SEAT_CAPACITIES = ['28 Seats', '30 Seats', '32 Seats', '36 Seats', '40 Seats', '52 Seats', '55 Seats'];

const AddBusRouteModal = ({ user, onClose, onSave }) => {
  // Helper to format user details safely without hardcoded dummy values ('abcd')
  const getUserDefaults = (userData) => ({
    name: userData?.name || '',
    email: userData?.emailOrPhone || userData?.email || '',
    phone: userData?.phone || ''
  });

  const [formData, setFormData] = useState({
    operatorName: '',
    coachNo: '',
    busType: '',
    seatCapacity: '36 Seats',
    district: '',
    arrivalTime: '',
    // Initialize user fields using the cleaned default function
    ...getUserDefaults(user)
  });

  // Update form if user prop loads asynchronously
  useEffect(() => {
    if (user) {
      setFormData((prev) => ({
        ...prev,
        ...getUserDefaults(user)
      }));
    }
  }, [user]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave(formData);
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        {/* Modal Header */}
        <div className="modal-header">
          <h2>Add New Bus Route</h2>
          <p>Select seat capacity and timing options</p>
          <button className="close-btn" onClick={onClose}>&times;</button>
        </div>

        <form onSubmit={handleSubmit}>
          {/* Photo Upload Section */}
          <div className="form-group upload-section">
            <label>Upload Bus Pictures</label>
            <div className="upload-box">
              <button type="button" className="btn-upload">
                + Choose Bus Photos
              </button>
            </div>
          </div>

          {/* Operator Name & Coach Number */}
          <div className="form-row">
            <div className="form-group">
              <label>Operator / Bus Name</label>
              <input
                type="text"
                name="operatorName"
                value={formData.operatorName}
                onChange={handleChange}
                placeholder="e.g. Shyamoli NR Travels"
              />
            </div>
            <div className="form-group">
              <label># Coach / Bus No</label>
              <input
                type="text"
                name="coachNo"
                value={formData.coachNo}
                onChange={handleChange}
                placeholder="e.g. DHAKA-METRO-11"
              />
            </div>
          </div>

          {/* Bus Type Category & Seat Capacity */}
          <div className="form-row">
            <div className="form-group">
              <label>Bus Type Category</label>
              <select
                name="busType"
                value={formData.busType}
                onChange={handleChange}
              >
                <option value="">-- Select Bus Type --</option>
                {BUS_TYPES.map((type, index) => (
                  <option key={index} value={type}>
                    {type}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label>Seat Capacity Option</label>
              <select
                name="seatCapacity"
                value={formData.seatCapacity}
                onChange={handleChange}
              >
                {SEAT_CAPACITIES.map((cap, index) => (
                  <option key={index} value={cap}>
                    {cap}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Actions */}
          <div className="modal-actions">
            <button type="button" className="btn-cancel" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="btn-save">
              Save Route
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddBusRouteModal;
